+///|
+fn PrivateKeyMatcher::plain(self : PrivateKeyMatcher, c : Char) -> Unit {
+  let c = if c >= 'A' && c <= 'Z' {
+    (c.to_int() + 32).unsafe_to_char()
+  } else {
+    c
+  }
+  self.tail.push(c)
+  if self.tail.length() > 32 {
+    ignore(self.tail.remove(0))
+  }
+  let suffix = fn(pattern : Array[Char]) {
+    self.tail.length() >= pattern.length() &&
+    ascii_match_at(self.tail, self.tail.length() - pattern.length(), pattern)
+  }
+  if !self.candidate {
+    self.candidate = suffix(
