+        private_key_end_prefix
+      } else {
+        private_key_begin_prefix
+      },
+    )
+  } else if suffix(private_key_end_marker) {
+    self.active = !self.active
+    self.candidate = false
+    self.tail.clear()
+  } else if suffix(private_key_dashes) {
+    self.candidate = false
+  }
