      if byte == b'\n' || byte == b'\r' {
        if oversized && scanner is Some(current) {
          current.feed(@utf8.decode_lossy(pending.to_bytes()))
          private_key.val = current.finish()
          scanner = None
        } else if pending.length() > 0 {
          let malformed : Ref[Bool] = { val: false, }
          let line = @utf8.decode(pending.to_bytes()) catch {
            _ => {
              self.details_truncated = true
              malformed.val = true
              @utf8.decode_lossy(pending.to_bytes())
            }
          }
          if malformed.val {
            let current = PrivateKeyScanner::new(private_key.val)
            current.feed(line)
            private_key.val = current.finish()
          } else if self.filter_output_line(line, private_key) is Some(safe) {
            if !capture && !raw_messages {
              self.remember_stderr(safe)
            }
            if raw_messages {

    AdapterError(detail) => (detail, false)
    InvalidConfig(detail) => (detail, false)
    SettingsProcessError(phase, code, status, detail) =>
      (
        "Orca settings process failed (exit \{status}, \{phase}: \{code})" +
        detail.map(value => ":\n" + value).unwrap_or(""),
        false,
      )
    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
    @json.InvalidNumber(position, _) =>
      (
        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
        true,
      )
    _ => (error.to_string(), false)
  }
