///|
fn sensitive_name(name : String) -> Bool {
  let normalized = name.to_lower().replace_all(old="-", new="_")
  if normalized == "ssh_auth_sock" {
    return false
  }
  if ["_enabled", "_disabled", "_count", "_mode", "_method"]
    .iter()
    .any(suffix => normalized.has_suffix(suffix)) {
    return false
  }
  let credential = credential_field(name, for_diagnostics=true)
  let name = name.to_lower()
  credential ||
  [
    "password", "passwd", "passphrase", "token", "secret", "api_key", "apikey", "auth",
    "credential", "private_key", "access_key", "storage_key", "cookie", "fnox_age_key",
  ]
  .iter()
  .any(marker => name.contains(marker))
}

///|
fn add_protected_secret(secrets : Array[String], value : String) -> Unit {
  if value == "" {
    return
  }
  let values = [value]
  for part in value.replace_all(old="\r", new="\n").split("\n") {
    if part.trim() != "" && part.length() < value.length() {
      values.push(part.to_owned())
    }
  }
  for item in values {
    if !secrets.contains(item) {
      secrets.push(item)
    }
    let encoded = Json::string(item).stringify()
    let escaped = encoded[1:encoded.length() - 1].to_owned()
    if escaped != item && !secrets.contains(escaped) {
      secrets.push(escaped)
    }
  }
}

///|
fn Progress::new(
  stage : String,
  environment? : Map[String, String],
  recording_override? : Bool,
  context? : Json,
  protected_secrets? : Array[String],
  protection_incomplete~ : Bool = false,
) -> Progress {
  let secrets = []
  for name, value in environment.unwrap_or(@env.get_env_vars()) {
    if sensitive_name(name) && value != "" {
      // Multiline credentials must also be masked in line-oriented output.
      add_protected_secret(secrets, value)
    }
  }
  if protected_secrets is Some(values) {
    for value in values {
      add_protected_secret(secrets, value)
    }
  }
  for value in create_recording.protected_secrets {
    add_protected_secret(secrets, value)
  }
  secrets.sort_by((a, b) => b.length().compare(a.length()))
  {
    stage,
    operations: {},
    builds: {},
    secrets,
    protection_incomplete: protection_incomplete ||
    create_recording.protection_incomplete,
    recording: recording_override.unwrap_or(
      environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
      Some("0"),
    ),
    context,
    phase_count: 0,
    private_key: false,
    classic_build: false,
    recent: [],
    failures: [],
    unrecognized: [],
    stderr_lines: [],
    details_truncated: false,
  }
}

///|
fn terminal_text(text : String) -> String? {
  let output = @buffer.Buffer(size_hint=256)
  let mut state = 0
  for c in text.iter() {
    match state {
      0 =>
        if c == '\u001b' {
          state = 1
        } else if c.to_int() < 32 && c != '\t' {
          return None
        } else {
          output.write_char_utf8(c)
        }
      1 =>
        if c == '[' {
          state = 2
        } else if c == ']' {
          state = 3
        } else {
          return None
        }
      2 => if c >= '@' && c <= '~' { state = 0 }
      3 => if c == '\u0007' { state = 0 } else if c == '\u001b' { state = 4 }
      _ => if c == '\\' { state = 0 } else { state = 3 }
    }
  }
  if state != 0 {
    None
  } else {
    Some(@utf8.decode_lossy(output.to_bytes()))
  }
}

///|
fn Progress::remember(
  self : Progress,
  message : String,
  warning~ : Bool,
) -> Unit {
  let lines = if warning { self.failures } else { self.recent }
  if lines.last() == Some(message) {
    return
  }
  if lines.length() == 8 {
    ignore(lines.remove(0))
    self.details_truncated = true
  }
  lines.push(message)
}

///|
fn Progress::failure_detail(self : Progress) -> String {
  let lines = self.failures +
    self.recent.filter(line => !self.failures.contains(line))
  let detail = if lines.is_empty() {
    "no readable error message from subprocess"
  } else {
    lines.join("\n")
  }
  detail +
  (if self.details_truncated {
    "\n[error details incomplete or truncated]"
  } else {
    ""
  })
}

///|
fn Progress::remember_unrecognized(self : Progress, text : String) -> Unit {
  if self.protection_incomplete {
    self.details_truncated = true
    let unavailable = "error detail unavailable because workspace protection values could not be read"
    if !self.unrecognized.contains(unavailable) {
      self.unrecognized.push(unavailable)
    }
    return
  }
  guard self.safe_message(text) is Some(safe) else {
    self.details_truncated = true
    return
  }
  if self.unrecognized.length() == 8 {
    ignore(self.unrecognized.remove(0))
    self.details_truncated = true
  }
  self.unrecognized.push(safe)
}

///|
fn Progress::remember_unrecognized_json(self : Progress, event : Json) -> Unit {
  if self.protection_incomplete {
    self.remember_unrecognized("")
    return
  }
  let truncated : Ref[Bool] = { val: false, }
  let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
  if truncated.val {
    self.details_truncated = true
  }
  self.remember_unrecognized(safe)
}

///|
fn Progress::remember_stderr(self : Progress, text : String) -> Unit {
  if !self.recording {
    return
  }
  let event = @json.parse(text) catch { _ => Json::null() }
  let normalized = if event != Json::null() {
    let truncated : Ref[Bool] = { val: false, }
    let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
    if truncated.val {
      self.details_truncated = true
    }
    safe
  } else {
    text
  }
  guard self.safe_message(normalized) is Some(safe) else {
    self.details_truncated = true
    return
  }
  if self.stderr_lines.length() == 8 {
    ignore(self.stderr_lines.remove(0))
    self.details_truncated = true
  }
  self.stderr_lines.push(safe)
}

