async fn Progress::message(
  self : Progress,
  text : String,
  debug~ : Bool,
  warning~ : Bool,
  emit~ : Bool = true,
) -> Unit {
  if self.protection_incomplete {
    self.details_truncated = true
    self.remember(
      "error detail unavailable because workspace protection values could not be read",
      warning=true,
    )
    return
  }
  for line in text.split("\n") {
    let text = line.trim().to_owned()
    if text == "" {
      continue
    }
    guard self.safe_message(text) is Some(safe) else {
      self.details_truncated = true
      continue
    }
    if !debug || warning {
      self.remember(safe, warning~)
    }
    if !emit {
      continue
    }
    if safe.has_prefix("#") {
      guard safe.split_once(" ") is Some((id, rest)) &&
        id.length() > 1 &&
        id[1:].iter().all(c => c >= '0' && c <= '9') else {
        continue
      }
      let detail = rest.trim().to_owned()
      guard detail.has_prefix("[") ||
        detail.has_prefix("DONE") ||
        detail.has_prefix("ERROR") ||
        detail.has_prefix("CACHED") else {
        continue
      }
      if detail.has_prefix("ERROR") && debug && !warning {
        self.remember(safe, warning=true)
      }
      if self.builds.get(id.to_owned()) == Some(detail) {
        continue
      }
      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
        self.builds.set(id.to_owned(), detail)
      }
      progress_message("Build " + id.to_owned() + ": " + detail)
    } else if classic_build_step(safe) {
      // Classic RUN output has no prefix. Only its own completion marker
      // ends this mode; phase events on another pipe can arrive ahead of it.
      self.classic_build = true
      progress_message("Build " + safe)
    } else if safe.has_prefix("Successfully built ") ||
      safe.has_prefix("Successfully tagged ") {
      self.classic_build = false
      progress_message("Build: " + safe)
    } else if self.classic_build && !warning {
      continue
    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
      progress_message(self.stage + ": " + safe)
    } else if !debug && safe.has_prefix("[credential") {
      progress_message(self.stage + ": " + safe)
    }
  }
}

///|
fn Progress::learn_event(self : Progress, event : Json, line : String) -> Unit {
  if event != Json::null() {
    let protected_values : DiagnosticProtectedValues = {
      secrets: [],
      visited: 0,
      incomplete: false,
    }
    diagnostic_protected_values(event, protected_values, line, false)
    if protected_values.incomplete ||
      self.secrets.length() + protected_values.secrets.length() > 1024 {
      self.protection_incomplete = true
      self.details_truncated = true
      self.recent.clear()
      self.failures.clear()
      self.unrecognized.clear()
      self.stderr_lines.clear()
    } else {
      for secret in protected_values.secrets {
        add_protected_secret(self.secrets, secret)
      }
      self.secrets.sort_by((a, b) => b.length().compare(a.length()))
    }
  }
}

///|
fn progress_json_text(text : String, truncated : Ref[Bool]) -> String {
  if !text.contains("\u001b") {
    return text
  }
  let parts : Array[String] = []
  for line in text.split("\n") {
    match terminal_text(line.to_owned()) {
      Some(safe) => parts.push(safe)
      None => {
        truncated.val = true
        return "[unavailable]"
      }
    }
  }
  parts.join("\n")
}

///|
fn progress_normalize_json(
  value : Json,
  truncated : Ref[Bool],
  depth : Int32,
) -> Json {
  if depth >= 64 {
    truncated.val = true
    return Json::string("[unavailable]")
  }
  match value {
    Json::String(text) => Json::string(progress_json_text(text, truncated))
    Json::Array(values) =>
      Json::array(
        values.map(item => progress_normalize_json(item, truncated, depth + 1)),
      )
    Json::Object(values) => {
      let result = Json::empty_object()
      for name, item in values {
        let key = progress_json_text(name, truncated)
        if field(result, key) is Some(_) {
          truncated.val = true
        } else {
          set_field(
            result,
            key,
            progress_normalize_json(item, truncated, depth + 1),
          )
        }
      }
      result
    }
    _ => value
  }
}

///|
fn Progress::filter_output_line(
  self : Progress,
  line : String,
  private_key : Ref[Bool],
) -> String? {
  let event = @json.parse(line) catch { _ => Json::null() }
  self.learn_event(event, line)
  let normalized = if event != Json::null() {
    let truncated : Ref[Bool] = { val: false, }
    let value = progress_normalize_json(event, truncated, 0)
    if truncated.val {
      self.details_truncated = true
      let scanner = PrivateKeyScanner::new(private_key.val)
      scanner.feed(line)
      private_key.val = scanner.finish()
      return None
    }
    value.stringify()
  } else {
    match terminal_text(line) {
      Some(text) => decode_diagnostic_escapes(text)
      None => {
        self.details_truncated = true
        let scanner = PrivateKeyScanner::new(private_key.val)
        scanner.feed(line)
        private_key.val = scanner.finish()
        return None
      }
    }
  }
  let scanner = PrivateKeyScanner::new(private_key.val)
  scanner.feed(normalized)
  let scanned_private = scanner.finish()
  let truncated : Ref[Bool] = { val: false, }
  let safe = mask_private_key(normalized, private_key, truncated)
  if truncated.val {
    self.details_truncated = true
  }
  if scanned_private && !private_key.val {
    self.details_truncated = true
    private_key.val = true
    guard safe is Some(safe) else { return None }
    let chars = safe.iter().to_array()
    let prefix = "-----begin ".iter().to_array()
    for index in 0..<chars.length() {
      if ascii_match_at(chars, index, prefix) {
        return Some(character_text(chars, 0, index) + "[private key redacted]")
      }
    }
    return None
  }
  safe
}

///|
async fn Progress::line(
  self : Progress,
  line : String,
  statuses~ : Bool,
  messages~ : Bool,
) -> Unit {
  if line.trim() == "" {
    return
  }
  let event = @json.parse(line) catch { _ => Json::null() }
  if field(event, "kind") == Some(Json::string("status")) {
    if field(event, "state") == Some(Json::string("failed")) &&
      field(event, "error") is Some(error) {
      for name in ["message", "hint"] {
        if field(error, name) is Some(Json::String(text)) {
          self.message(
            text,
            debug=false,
            warning=true,
            emit=messages || statuses,
          )
        }
      }
      self.remember_unrecognized_json(event)
    }
    if statuses || messages {
      self.status(event)
    }
    return
  }
  // Result envelopes and arbitrary structured responses are never log text.
  if field(event, "kind") == Some(Json::string("result")) {
    if field(event, "outcome") == Some(Json::string("success")) &&
      field(event, "warnings") is Some(Json::Array(warnings)) {
      for warning in warnings {
        match warning {
          Json::String(text) =>
            self.message(
              text,
              debug=false,
              warning=true,
              emit=messages || statuses,
            )
          _ => {
            let truncated : Ref[Bool] = { val: false, }
            let safe = diagnostic_json(warning, {}, self.secrets, truncated, 0).stringify()
            if truncated.val {
              self.details_truncated = true
            }
            self.message(safe, debug=false, warning=true, emit=false)
          }
        }
      }
    }
    if field(event, "outcome") != Some(Json::string("success")) &&
      (
        field(event, "error") is Some(_) ||
        field(event, "message") is Some(_) ||
        field(event, "code") is Some(_) ||
        field(event, "outcome") == Some(Json::string("failure")) ||
        field(event, "outcome") == Some(Json::string("error"))
      ) {
      self.remember_unrecognized_json(event)
    }
    return
  }
  if field(event, "kind") == Some(Json::string("orca-env-devsy-server-exit")) {
    return
  }
  if event is Json::Object(_) {
    let kind = field(event, "kind")
    guard kind == None ||
      kind == Some(Json::string("log")) ||
      kind == Some(Json::string("error")) else {
      self.remember_unrecognized_json(event)
      return
    }
    let message = match field(event, "msg") {
      Some(value) => Some(value)
      None =>
        match field(event, "message") {
          Some(value) => Some(value)
          None =>
            match field(event, "error") {
              Some(Json::Object(_) as value) => field(value, "message")
              value => value
            }
        }
    }
    guard message is Some(Json::String(text)) else {
      self.remember_unrecognized_json(event)
      return
    }
    let level = field(event, "level")
    self.message(
      text,
      debug=level == Some(Json::string("debug")) ||
        level == Some(Json::string("trace")),
      warning=kind == Some(Json::string("error")) ||
        level == Some(Json::string("warn")) ||
        level == Some(Json::string("error")),
      emit=messages || (statuses && kind != None),
    )
  } else {
    if event != Json::null() {
      self.remember_unrecognized_json(event)
      return
    }
    // Malformed JSON and binary output are not a safe free-text fallback.
    let text = line.trim().to_owned()
    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
      self.message(text, debug=false, warning=true, emit=messages)
      return
    }
    if text.has_prefix("{") || text.has_prefix("[") {
      self.details_truncated = true
      self.remember_unrecognized(text)
      return
    }
    self.message(
      text,
      debug=text.contains(" DEBUG ") ||
        text.contains(" TRACE ") ||
        text.has_prefix("DEBUG ") ||
        text.has_prefix("TRACE "),
      warning=text.contains(" WARN ") ||
        text.contains(" ERROR ") ||
        text.has_prefix("WARN ") ||
        text.has_prefix("ERROR "),
      emit=messages,
    )
  }
}

///|
async fn Progress::stderr_line(
  self : Progress,
  line : String,
  statuses~ : Bool,
  messages~ : Bool,
) -> Unit {
  let event = @json.parse(line) catch { _ => Json::null() }
  if event != Json::null() {
    self.line(line, statuses~, messages~)
    let truncated : Ref[Bool] = { val: false, }
    let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
    if truncated.val {
      self.details_truncated = true
    }
    if field(event, "kind") == Some(Json::string("error")) ||
      [Some(Json::string("warn")), Some(Json::string("error"))].contains(
        field(event, "level"),
      ) ||
      field(event, "state") == Some(Json::string("failed")) {
      self.message(safe, debug=false, warning=true, emit=false)
    } else {
      self.remember_unrecognized(safe)
    }
    return
  } else if event == Json::null() &&
    (line.trim().has_prefix("[") || line.trim().has_prefix("{")) {
    self.details_truncated = true
    self.message(line, debug=false, warning=true, emit=false)
    return
  }
  self.line(line, statuses~, messages~)
}

