          stable_activity=evidence_stable_activity,
          secret_states=stage == "server-environment",
          stable_operation=evidence_stable_operation,
          stable_arguments=[
            "create-arguments", "create-options", "resolve-context",
          ].contains(stage),
        ),
      )
    } else {
      evidence_truncated.val = true
    }
  }
  if evidence_truncated.val {
    set_field(event, "evidenceTruncated", Json::boolean(true))
    set_field(event, "completeness", Json::string("partial"))
  }
  if details_truncated ||
    evidence_truncated.val ||
    field(event, "detailsTruncated") == Some(Json::boolean(true)) {
    diagnostic_recording_health.run_partial = true
  }
  if run_completeness is Some(value) {
    set_field(event, "runCompleteness", Json::string(value))
  }
  if os_errno is Some(code) && code > 0 && code < 4096 {
    set_field(event, "osErrno", Json::number(code.to_double()))
  }
  if exit_code is Some(code) {
    set_field(event, "exitCode", Json::number(code.to_double()))
  }
  for pair in [("errorType", error_type), ("phase", phase)] {
    if pair.1 is Some(text) {
      set_field(event, pair.0, Json::string(text))
    }
  }
  if duration_ms is Some(value) {
    set_field(event, "durationMs", Json::number(value))
  }
  if attempt is Some(value) {
    set_field(event, "attempt", Json::number(value.to_double()))
  }
  if timeout_ms is Some(value) {
    set_field(event, "timeoutMs", Json::number(value.to_double()))
  }
  if retry_delay_ms is Some(value) {
    set_field(event, "retryDelayMs", Json::number(value.to_double()))
  }
  let failed = error_type is Some(_) ||
    ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
      status,
    )
  if diagnostic_pending.length() >= 64 {
    let mut evict = -1
    if failed {
      for index in diagnostic_pending_inflight.val..<diagnostic_pending.length() {
        if !diagnostic_pending[index].failed {
          evict = index
          break
        }
      }
      if evict < 0 &&
        diagnostic_pending_inflight.val < diagnostic_pending.length() {
        evict = diagnostic_pending_inflight.val
      }
    }
    if evict < 0 {
      diagnostic_recording_failed("buffer_full", phase="buffer", event_time~)
      return
    }
    let removed = diagnostic_pending.remove(evict)
    diagnostic_pending.push({ event, failed, time: event_time, })
    diagnostic_recording_failed(
      "buffer_full",
      phase="buffer",
      event_time=removed.time,
    )
    try_flush_diagnostic_recording()
    return
  }
  diagnostic_pending.push({ event, failed, time: event_time, })
  try_flush_diagnostic_recording()
}

async fn Progress::read_output(
  self : Progress,
  reader : @process.ReadFromProcess,
  capture~ : Bool,
  statuses~ : Bool = false,
  messages~ : Bool = false,
  raw_messages~ : Bool = false,
) -> String {
  let output = @buffer.Buffer(size_hint=4096)
  let pending = @buffer.Buffer(size_hint=4096)
  let private_key : Ref[Bool] = { val: false, }
  let mut scanner : PrivateKeyScanner? = None
  let mut oversized = false
  let mut tail = ""
  while reader.read_some(max_len=4096) is Some(chunk) {
    if capture {
      output.write_bytes(chunk)
    } else {
      tail += @utf8.decode_lossy(chunk)
      if tail.length() > 8192 {
        tail = tail[tail.length() - 8192:].to_owned()
      }
    }
    for byte in chunk {
      if byte == b'\n' || byte == b'\r' {
        if oversized && scanner is Some(current) {
          current.feed(@utf8.decode_lossy(pending.to_bytes()))
          private_key.val = current.finish()
          scanner = None
        } else if pending.length() > 0 {
          let malformed : Ref[Bool] = { val: false, }
          let line = @utf8.decode(pending.to_bytes()) catch {
            _ => {
              self.details_truncated = true
              malformed.val = true
              @utf8.decode_lossy(pending.to_bytes())
            }
          }
          if malformed.val {
            let current = PrivateKeyScanner::new(private_key.val)
            current.feed(line)
            private_key.val = current.finish()
          } else if self.filter_output_line(line, private_key) is Some(safe) {
            if !capture && !raw_messages {
              self.remember_stderr(safe)
            }
            if raw_messages {
              self.message(safe, debug=false, warning=true, emit=false)
            } else if capture {
              self.line(safe, statuses~, messages~)
            } else {
              self.stderr_line(safe, statuses~, messages~)
            }
          }
        }
        pending.reset()
        oversized = false
      } else if !oversized {
        if pending.length() == 65536 {
          let current = PrivateKeyScanner::new(private_key.val)
          current.feed(@utf8.decode_lossy(pending.to_bytes()))
          scanner = Some(current)
          pending.reset()
          pending.write_byte(byte)
          oversized = true
          self.details_truncated = true
        } else {
          pending.write_byte(byte)
        }
      } else {
        pending.write_byte(byte)
        if pending.length() >= 4096 && scanner is Some(current) {
          current.feed(@utf8.decode_lossy(pending.to_bytes()))
          pending.reset()
        }
      }
    }
  }
  if oversized && scanner is Some(current) {
    current.feed(@utf8.decode_lossy(pending.to_bytes()))
    private_key.val = current.finish()
  } else if pending.length() > 0 {
    let malformed : Ref[Bool] = { val: false, }
    let line = @utf8.decode(pending.to_bytes()) catch {
      _ => {
        self.details_truncated = true
        malformed.val = true
        @utf8.decode_lossy(pending.to_bytes())
      }
    }
    let masked = diagnostic_partial_secret(line, self.secrets)
    if masked != line {
      self.details_truncated = true
    }
    if malformed.val {
      let current = PrivateKeyScanner::new(private_key.val)
      current.feed(masked)
      private_key.val = current.finish()
    } else if self.filter_output_line(masked, private_key) is Some(safe) {
      if !capture && !raw_messages {
        self.remember_stderr(safe)
      }
      if raw_messages {
        self.message(safe, debug=false, warning=true, emit=false)
      } else if capture {
        self.line(safe, statuses~, messages~)
      } else {
        self.stderr_line(safe, statuses~, messages~)
      }
    }
  }
  if capture {
    @utf8.decode(output.to_bytes())
  } else {
    tail
  }
}

    _ => ()
  }
}

///|
fn diagnostic_json(
  value : Json,
  environment : Map[String, String],
  protected_secrets : Array[String],
  truncated : Ref[Bool],
  depth : Int32,
  stable_activity~ : Bool = false,
  secret_states~ : Bool = false,
  stable_operation~ : Bool = false,
  stable_arguments~ : Bool = false,
  parent~ : String = "",
) -> Json {
  let protected_secrets = if depth == 0 {
    let found : DiagnosticStructuredSecrets = {
      values: [],
      visited: 0,
      incomplete: false,
    }
    diagnostic_structured_secrets(value, found)
    if found.incomplete {
      truncated.val = true
      return { "reason": "protected_value_limit", "detailsTruncated": true }
    }
    protected_secrets + found.values
  } else {
    protected_secrets
  }
  if depth >= 64 {
    truncated.val = true
    return Json::string("[nested evidence omitted]")
  }
  match value {
    Json::Object(values) => {
      let result = Json::empty_object()
      for name, item in values {
        let key = name.to_lower().replace_all(old="_", new="")
        let safe_name = if (
            stable_arguments &&
            [
              "arguments", "value", "source", "argumentCount", "reason", "command",
              "home", "context", "state", "effectiveContext",
            ].contains(name)
          ) ||
          (
            stable_operation &&
            (
              (
                depth == 0 &&
                ["operationId", "workspaceId", "invocation"].contains(name)
              ) ||
              (
                depth == 1 &&
                [
                  "command", "resolvedProgram", "lookupPath", "workingDirectory",
                  "sshAuthSock",
                ].contains(name)
              )
            )
          ) ||
          (
            stable_activity &&
            [
              "schemaVersion", "observedAt", "activity", "reason", "terminals", "chats",
              "errors", "worktreeId", "agent", "type", "state", "programState", "sessionId",
              "workspaceId", "source", "code", "id", "uid", "context", "provider",
              "identityVerified", "vmStatus", "outcome", "evidence", "evidenceTruncated",
              "workspaces", "discoveryErrors", "action", "failed", "detailsTruncated",
              "error", "autoStop", "orcaVersion", "handle", "connected", "foregroundProcess",
              "hasChildProcesses", "processEvidence", "verdict", "capturedAgeMs",
              "ptyIncarnationId", "observationEpoch", "stateStartedAt", "updatedAt",
              "working", "queuedMessages", "actionablePrompts", "backgroundTasks",
            ].contains(name)
          ) {
          name
        } else {
          diagnostic_text(name, environment~, protected_secrets~)
        }
        if field(result, safe_name) is Some(_) {
          truncated.val = true
          continue
        }
        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
          truncated.val = true
        }
        set_field(
          result,
          safe_name,
          if credential_field(name, for_diagnostics=true) ||
            key == "pairingcode" {
            if secret_states &&
              field(item, "state") is Some(Json::String(state)) &&
              ["unset", "empty", "set"].contains(state) {
              let masked : Json = { "state": state }
              if field(item, "value") is Some(_) {
                set_field(masked, "value", Json::string("[redacted]"))
              }
              if field(item, "truncated") == Some(Json::boolean(true)) {
                set_field(masked, "truncated", Json::boolean(true))
                truncated.val = true
              }
              masked
            } else {
              Json::string("[redacted]")
            }
          } else if stable_activity &&
            name == "activity" &&
            (
              item == Json::string("idle") ||
              item == Json::string("active") ||
              item == Json::string("unknown")
            ) {
            item
          } else if stable_activity &&
            parent == "agent" &&
            item is Json::String(text) &&
            (
              (
                name == "state" &&
                ["working", "waiting", "blocked", "monitoring", "done"].contains(
                  text,
                )
              ) ||
              (
                name == "programState" &&
                ["working", "blocked", "idle"].contains(text)
              )
            ) {
            item
          } else {
            diagnostic_json(
              item,
              environment,
              protected_secrets,
              truncated,
              depth + 1,
              stable_activity~,
              secret_states~,
              stable_operation~,
              stable_arguments~,
              parent=name,
            )
          },
        )
      }
      result
    }
    Json::Array(values) =>
      Json::array(
        values.map(item => {
          diagnostic_json(
            item,
            environment,
            protected_secrets,
            truncated,
            depth + 1,
            stable_activity~,
            secret_states~,
            stable_operation~,
            stable_arguments~,
            parent~,
          )
        }),
      )
    Json::String(text) => {
      let safe = diagnostic_text(text, environment~, protected_secrets~)
      if safe.has_suffix("\n[error details incomplete or truncated]") {
        truncated.val = true
      }
      Json::string(safe)
    }
    _ => value
  }
}

