///|
async fn try_flush_diagnostic_recording() -> Unit {
  if diagnostic_write_active.val ||
    (diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0) {
    return
  }
  diagnostic_write_active.val = true
  defer {
    diagnostic_write_active.val = false
  }
  let mut failure_phase = "directory"
  let mut waiting_for_lock = false
  let mut health_changed = false
  @async.with_timeout(50, async fn() {
    let dir = adapter_state_home()
    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
    @fs.chmod(dir, 0o700)
    let path = dir + "/events.jsonl"
    let lock_path = dir + "/events.lock"
    failure_phase = "lock"
    if @fs.exists(lock_path) &&
      @fs.kind(lock_path, follow_symlink=false) != @fs.FileKind::Regular {
      diagnostic_recording_warning("invalid_lock", phase=failure_phase)
      return
    }
    let lock = @fs.open(
      lock_path,
      mode=ReadWrite,
      create_mode=OpenOrCreate,
      permission=0o600,
    )
    defer lock.close()
    if !lock.try_lock(Exclusive) {
      waiting_for_lock = true
      let started_waiting = @env.now()
      let mut acquired = false
      while !diagnostic_recording_health.incident &&
            @env.now() - started_waiting < 20UL {
        @async.sleep(1)
        if lock.try_lock(Exclusive) {
          acquired = true
          break
        }
      }
      if !acquired {
        diagnostic_recording_warning("lock_busy", phase=failure_phase)
        return
      }
      waiting_for_lock = false
    }
    failure_phase = "inspect"
    if @fs.exists(path) &&
      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
