          )
          set_field(marker, "missingRange", Json::string("unknown"))
          prefix += marker.stringify() + "\n"
          prefix_markers += 1
          retained = Some(
            @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:complete]),
          )
          replace = true
        }
      }
      if terminal && retained is None {
        let bytes = FixedArray::make(size.to_int(), b'\x00')
        let read = file.read_at(bytes, position=0L)
