            name == "activity" &&
            (
              item == Json::string("idle") ||
              item == Json::string("active") ||
              item == Json::string("unknown")
            ) {
            item
          } else if stable_activity &&
            parent == "agent" &&
            item is Json::String(text) &&
            (
              (
                name == "state" &&
                ["working", "waiting", "blocked", "monitoring", "done"].contains(
                  text,
