///|
fn recording_from_environment(environment : Json) -> Bool {
  match environment {
    Json::Object(values) =>
      match values.get("ORCA_ENV_DEVSY_RECORDING") {
        None => true
        Some(Json::String(value)) => value != "0"
        _ => false
      }
    _ => false
  }
}

///|
fn workspace_recording(state : Json) -> Bool {
  match field(state, "diagnosticRecording") {
    Some(value) if value == Json::boolean(false) => return false
    Some(value) if value == Json::boolean(true) => return true
    _ => ()
  }
  match field(state, "executionEnvironment") {
    Some(environment) => recording_from_environment(environment)
    None => @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0")
  }
}

///|
async fn diagnostic_read_file(path : String, limit : Int64) -> String? {
  @async.with_timeout(250, async fn() {
    guard @fs.kind(path, follow_symlink=false) == @fs.FileKind::Regular &&
      @fs.file_size(path) <= limit else {
      return None
    }
    Some(@fs.read_file(path).text())
  }) catch {
    error => if @async.is_being_cancelled() { raise error } else { None }
  }
}

///|
async fn snapshot_workspace_recording(state : Json, directory : String) -> Unit {
  let mut reason = "enabled"
  let enabled = if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
    reason = "process_opt_out"
    false
  } else {
    let value = try {
      guard diagnostic_read_file(directory + "/environment.json", 4194304L)
        is Some(raw) else {
        raise AdapterError("Saved recording settings unavailable")
      }
      let environment = @json.parse(raw)
      guard environment is Json::Object(_) else {
        raise AdapterError("Invalid saved recording settings")
      }
      Some(recording_from_environment(environment))
    } catch {
      error => if @async.is_being_cancelled() { raise error } else { None }
    }
    if value is None {
      reason = "workspace_recording_unknown"
      diagnostic_recording_warning(
        "workspace_recording_unknown",
        phase="configuration",
      )
    }
    if value == Some(false) {
      reason = "workspace_opt_out"
    }
    value.unwrap_or(false)
  }
  set_field(state, "diagnosticRecording", Json::boolean(enabled))
  set_field(state, "diagnosticRecordingReason", Json::string(reason))
}

///|
async fn saved_workspace_secrets(
  state : Json,
  for_output~ : Bool = false,
  include_pairing~ : Bool = true,
) -> Array[String]? {
  if !for_output && !state_recording(state) {
    return Some([])
  }
  try {
    let directory = required(state, "tunnelDirectory")
    guard diagnostic_read_file(directory + "/environment.json", 4194304L)
      is Some(raw) else {
      return None
    }
    let saved = @json.parse(raw)
    guard saved is Json::Object(values) else { return None }
    let environment : Map[String, String] = Map([])
    for name, value in values {
      guard value is Json::String(value) else { return None }
      environment.set(name, value)
    }
    let secrets = Progress::new("diagnostic-evidence", environment~).secrets
    let invocation = saved_command(state)
    let sources = invocation.mapi((index, _) => "command[\{index}]")
    let (_, invocation_secrets, invocation_incomplete) = up_arguments_evidence(
      invocation, sources,
    )
    guard !invocation_incomplete else { return None }
    for value in invocation_secrets {
      add_protected_secret(secrets, value)
    }
    if include_pairing {
      guard workspace_pairing_secrets(state) is Some(pairing) else {
        return None
      }
      for value in pairing {
        secrets.push(value)
      }
    }
    Some(secrets)
  } catch {
    error => if @async.is_being_cancelled() { raise error } else { None }
  }
}

///|
async fn workspace_output_secrets(state : Json) -> Array[String]? {
  guard field(state, "tunnelDirectory") is Some(Json::String(directory)) else {
    return Some([])
  }
  if !@fs.exists(directory + "/state.json") &&
    !@fs.exists(directory + "/environment.json") &&
    !@fs.exists(directory + "/pairing-code") {
    return Some([])
  }
  saved_workspace_secrets(state, for_output=true)
}

///|
async fn workspace_pairing_value(state : Json) -> String? {
  try {
    let path = required(state, "tunnelDirectory") + "/pairing-code"
    if !@fs.exists(path) {
      return Some("")
    }
    diagnostic_read_file(path, 65536L)
  } catch {
    error => if @async.is_being_cancelled() { raise error } else { None }
  }
}

///|
async fn workspace_pairing_secrets(state : Json) -> Array[String]? {
  guard workspace_pairing_value(state) is Some(pairing) else { return None }
  let secrets = []
  add_protected_secret(secrets, pairing)
  Some(secrets)
}

///|
async fn workspace_error_detail(state : Json, error : Error) -> String {
  let environment = workspace_environment(state)
  guard saved_workspace_secrets(state, for_output=true) is Some(secrets) else {
    return "Error detail unavailable because workspace protection values could not be read"
  }
  diagnostic_text(
    diagnostic_error(error, environment~),
    environment~,
    protected_secrets=secrets,
  )
}

///|
async fn workspace_text(state : Json, value : String) -> String {
  guard workspace_output_secrets(state) is Some(secrets) else {
    return "[unavailable]"
  }
  diagnostic_text(
    value,
    environment=workspace_environment(state),
    protected_secrets=secrets,
  )
}

///|
async fn record_discovery_error(
  stage : String,
  directory : String,
  phase : String,
  error : Error,
) -> (Bool, Array[String]) {
  let tracking : Json = { "tunnelDirectory": directory }
  snapshot_workspace_recording(tracking, directory)
  if !operation_recording(tracking) {
    return (false, [])
  }
  guard saved_workspace_secrets(tracking) is Some(secrets) else {
    suppress_workspace_recording(tracking)
    return (false, [])
  }
  save_diagnostic(
    stage,
    "failed",
    error_type="saved_state_invalid",
    phase~,
    tunnel_directory=directory,
    error_message=diagnostic_error(error),
    protected_secrets=secrets,
    recording=true,
  )
  (true, secrets)
}

///|
async fn record_selection_failure(
  stage : String,
  state : Json,
  phase : String,
  error_type : String,
  detail : String,
) -> Unit {
  let directory = required(state, "tunnelDirectory")
  snapshot_workspace_recording(state, directory)
  if !operation_recording(state) {
    return
  }
  guard saved_workspace_secrets(state) is Some(secrets) else {
    suppress_workspace_recording(state)
    return
  }
  save_diagnostic(
    stage,
    "failed",
    error_type~,
    phase~,
    tunnel_directory=directory,
    error_message=detail,
    evidence={ "workspaceId": required(state, "workspaceId") },
    environment=workspace_environment(state),
    protected_secrets=secrets,
    recording=true,
  )
}

///|
async fn suppress_workspace_recording(state : Json) -> Unit {
  if state_recording(state) {
    set_field(
      state,
      "diagnosticRecordingReason",
      Json::string("protected_values_unavailable"),
    )
    diagnostic_recording_failed(
      "protected_values_unavailable",
      phase="redaction",
    )
  }
  set_field(state, "diagnosticRecording", Json::boolean(false))
}

///|
async fn record_batch_omission(
  stage : String,
  states : Array[Json],
  discovery_recording : Bool,
) -> Unit {
  if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
    return
  }
  let reasons : Array[Json] = []
  for state in states {
    if !workspace_recording(state) {
      let reason = match field(state, "diagnosticRecordingReason") {
        Some(Json::String(value)) if [
            "workspace_opt_out", "workspace_recording_unknown", "protected_values_unavailable",
          ].contains(value) => value
        _ => "workspace_recording_unavailable"
      }
      let value = Json::string(reason)
      if !reasons.contains(value) {
        reasons.push(value)
      }
    }
  }
  if !discovery_recording {
    reasons.push(Json::string("discovery_omitted"))
  }
  if reasons.is_empty() {
    reasons.push(Json::string("recording_unavailable"))
  }
  save_diagnostic(
    stage,
    "incomplete",
    error_type="batch_evidence_omitted",
    evidence={ "scope": "batch_result", "reasons": Json::array(reasons) },
    evidence_incomplete=true,
    recording=true,
  )
}

///|
fn operation_recording(state : Json) -> Bool {
  @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0") &&
  workspace_recording(state)
}

///|
fn state_recording(state : Json) -> Bool {
  match @env.args() {
    [_, "--supervisor" | "--ssh-proxy", ..] => workspace_recording(state)
    _ => operation_recording(state)
  }
}

///|
pub let usage : String = "Usage: orca-env-devsy <status|stop [--force]|resume> --provider <name> [--jobs <n>]\n       orca-env-devsy recipe <create|resume|suspend|destroy|recover|restart>\n       orca-env-devsy <recover|restart>\n       orca-env-devsy update [--provider <name> [--workspace <id>]] [--force]\n"

///|
priv struct BulkOptions {
  provider : String
  jobs : Int32
  force : Bool
}

///|
fn bulk_options(mode : String, args : Array[String]) -> BulkOptions raise {
  let mut provider = None
  let mut jobs = 4
  let mut force = false
  let mut i = 0
  while i < args.length() {
    match args[i] {
      "--provider" if i + 1 < args.length() && provider is None => {
        i += 1
        provider = Some(args[i])
      }
      "--jobs" if i + 1 < args.length() => {
        i += 1
        jobs = @string.parse_int(args[i])
      }
      "--force" if mode == "stop" && !force => force = true
      _ => raise AdapterError("Invalid bulk option: " + args[i])
    }
    i += 1
  }
  guard provider is Some(provider) &&
    valid_context(provider) &&
    jobs > 0 &&
    jobs <= 64 else {
    raise AdapterError(
      "--provider is required; --jobs must be between 1 and 64",
    )
  }
  { provider, jobs, force, }
}

///|
async fn observe_activity(state : Json, pairing_out? : Ref[String?]) -> Json {
  let directory = required(state, "tunnelDirectory")
  let path = directory + "/pairing-code"
  let pairing = (async fn() {
    let mut os_errno = None
    errdefer save_diagnostic(
      "activity-probe",
      "failed",
      error_type="pairing_code_read_failed",
      phase="input",
      os_errno?,
      tunnel_directory=directory,
      recording=state_recording(state),
    )
    try {
      if @fs.exists(path) {
        @fs.read_file(path).text()
      } else {
        ""
      }
    } catch {
      @os_error.OSError(code, ..) as error => {
        os_errno = Some(code)
        raise error
      }
      error => raise error
    }
  })()
  if pairing_out is Some(output) {
    output.val = Some(pairing)
  }
  let script = activity_command(state)
  let (input, writer) = @process.write_to_process()
  defer writer.close()
  let (output, reader) = @process.read_from_process()
  defer output.close()
  let (errors, stderr) = @process.read_from_process()
  defer errors.close()
  let protected_values = if field(state, "executionEnvironment") is Some(_) {
    Some([])
  } else {
    saved_workspace_secrets(state, for_output=true, include_pairing=false)
  }
  if protected_values is None && state_recording(state) {
    suppress_workspace_recording(state)
  }
  let progress = Progress::new(
    "activity-probe",
    environment=workspace_environment(state),
    recording_override=state_recording(state),
    protected_secrets?=protected_values,
    protection_incomplete=protected_values is None,
  )
  if pairing != "" {
    add_protected_secret(progress.secrets, pairing)
    progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
  }
  let mut phase = "master"
  let mut exit_code = None
  let mut failure_codes : Array[Json] = []
  errdefer save_diagnostic(
    "activity-probe",
    "failed",
    error_type="observation_failed",
    phase~,
    exit_code?,
    evidence={ "errors": Json::array(failure_codes) },
    error_message=progress.failure_detail(),
    details_truncated=progress.details_truncated,
    tunnel_directory=directory,
    recording=state_recording(state),
    environment=workspace_environment(state),
    protected_secrets=progress.secrets,
  )
  @async.with_timeout(30000, async fn() {
    let args = mux_ssh_args(state)
    phase = "spawn"
    @async.with_task_group(async fn(group) {
      let child = @process.spawn(
        group,
        workspace_program(state, "ssh"),
        extra_env=workspace_environment(state),
        inherit_env=false,
        cwd?=workspace_directory(state).map(path => path[:]),
        args + [script],
        stdin=input,
        stdout=reader,
        stderr~,
      )
      let collected_errors = group.spawn(async fn() {
        ignore(progress.read_output(errors, capture=false))
      })
      let reading = group.spawn(async fn() {
        let buffer = @buffer.Buffer()
        let bytes = FixedArray::make(4096, b'\x00')
        while true {
          let count = output.read(bytes)
          if count == 0 {
            break
          }
          guard buffer.length() + count <= 4194304 else {
            raise AdapterError("Activity response too large")
          }
          buffer.write_bytes(Bytes::from_array(bytes[:count].to_owned()))
        }
        @utf8.decode(buffer.to_bytes())
      })
      let payload : Json = { "pairingCode": pairing }
      writer.write(payload.stringify())
      writer.close()
      phase = "result"
      let code = child.wait()
      exit_code = Some(code)
      collected_errors.wait()
      phase = "schema"
      let raw = reading.wait()
      let parsed = Some(@json.parse(raw)) catch { _ => None }
      if parsed is Some(value) {
        let found : DiagnosticStructuredSecrets = {
          values: [],
          visited: 0,
          incomplete: false,
        }
        diagnostic_structured_secrets(value, found)
        if found.incomplete {
          progress.protection_incomplete = true
          progress.details_truncated = true
        } else {
          for secret in found.values {
            add_protected_secret(progress.secrets, secret)
          }
          progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
        }
      }
      if parsed is Some(value) &&
        !progress.protection_incomplete &&
        field(value, "errors") is Some(Json::Array(errors)) {
        failure_codes = errors.filter_map(error => {
          match field(error, "code") {
            Some(Json::String(code)) if code.length() > 0 &&
              code.length() <= 80 &&
              code.iter().all(c => (c >= 'a' && c <= 'z') || c == '_') =>
              Some(Json::string(code))
            _ => None
          }
        })
      }
      guard code == 0 else {
        raise AdapterError(
          "Remote activity probe failed (exit \{code}; errors " +
          Json::array(failure_codes).stringify() +
          ")",
        )
      }
      guard parsed is Some(value) else {
        raise AdapterError("Invalid activity JSON")
      }
      guard field(value, "schemaVersion") == Some(Json::number(1)) &&
        ["idle", "active", "unknown"].contains(required(value, "activity")) else {
        raise AdapterError("Invalid activity response")
      }
      value
    })
  })
}

