///|
fn workspace_environment(state : Json) -> Map[String, String] {
  let environment = match field(state, "executionEnvironment") {
    Some(Json::Object(values)) => {
      let result : Map[String, String] = Map([])
      for (name, value) in values {
        if value is Json::String(value) {
          result.set(name, value)
        }
      }
      result
    }
    _ => @env.get_env_vars()
  }
  for name in location_variables {
    match field(field(state, "devsyEnv").unwrap_or(Json::null()), name) {
      Some(Json::String(value)) => environment.set(name, value)
      _ => environment.remove(name)
    }
  }
  environment
}

///|
fn workspace_directory(state : Json) -> String? {
  match field(state, "hostDirectory") {
    Some(Json::String(value)) => Some(value)
    _ => None
  }
}

///|
async fn workspace_program(state : Json, program : String) -> String {
  let cwd = workspace_directory(state).unwrap_or(
    @env.current_dir().unwrap_or("/"),
  )
  if program.has_prefix("/") {
    return program
  }
  if program.contains("/") {
    return cwd + "/" + program
  }
  let path = field(field(state, "devsyEnv").unwrap_or(Json::null()), "PATH")
  let path = match path {
    Some(Json::String(value)) => value
    _ => "/usr/bin:/bin"
  }
  let mut fallback = None
  for directory in path.split(":") {
    let directory = if directory.has_prefix("/") {
      directory.to_owned()
    } else {
      cwd + "/" + directory.to_owned()
    }
    let candidate = directory + "/" + program
    if fallback is None {
      fallback = Some(candidate)
    }
    if transport_access(@utf8.encode(candidate + "\u0000"), 1) == 0 &&
      @fs.kind(candidate) != @fs.FileKind::Directory {
      return candidate
    }
  }
  fallback.unwrap_or(cwd + "/" + program)
}

///|
async fn devsy_result(
  state : Json,
  args : Array[String],
  stage : String,
  extra_secrets? : Array[String],
  extra_protection_incomplete~ : Bool = false,
) -> (Int32, String, String) {
  let environment = workspace_environment(state)
  let protected_values = workspace_output_secrets(state)
  if protected_values is None {
    suppress_workspace_recording(state)
  }
  let invocation = saved_command(state)
  let invocation_sources = invocation.mapi((index, _) => "command[\{index}]")
  let (_, invocation_secrets, invocation_incomplete) = up_arguments_evidence(
    invocation, invocation_sources,
  )
  let logging = if devsy_progress_stage(stage) {
    ["--log-level", "debug", "--log-output", "json"]
  } else {
    []
  }
  let secrets = protected_values.unwrap_or([]) +
    extra_secrets.unwrap_or([]) +
    invocation_secrets
  let program = workspace_program(state, invocation[0])
  let cwd = workspace_directory(state).unwrap_or(
    @env.current_dir().unwrap_or("/"),
  )
  let lookup_path = match
    field(field(state, "devsyEnv").unwrap_or(Json::null()), "PATH") {
    Some(Json::String(value)) => value
    _ => "/usr/bin:/bin"
  }
  let path_protection = Progress::new(
    stage,
    environment~,
    protected_secrets=secrets,
    protection_incomplete=protected_values is None ||
      extra_protection_incomplete ||
      invocation_incomplete,
  )
  let lookup_path = redact_known_values(lookup_path, path_protection.secrets)
    .split(":")
    .map(entry => Json::string(entry.to_owned()))
    .to_array()
  let result = command_result(
    program,
    invocation[1:].to_owned() + devsy_args(state) + logging + args,
    stage,
    environment~,
    recording_override=state_recording(state),
    protected_secrets=secrets,
    protection_incomplete=protected_values is None ||
      extra_protection_incomplete ||
      invocation_incomplete,
    invocation_evidence={
      "command": Json::array(invocation.map(Json::string)),
      "resolvedProgram": program,
      "lookupPath": Json::array(lookup_path),
      "workingDirectory": cwd,
      "sshAuthSock": environment
      .get("SSH_AUTH_SOCK")
      .map(Json::string)
      .unwrap_or(Json::null()),
    },
    cwd?=workspace_directory(state).map(path => path[:]),
    target?=field(state, "workspaceId").map(value => {
      if value is Json::String(name) {
        name
      } else {
        ""
      }
    }),
  )
  result
}

