  extra_protection_incomplete~ : Bool = false,
) -> (Int32, String, String) {
  let environment = workspace_environment(state)
  let protected_values = workspace_output_secrets(state)
  if protected_values is None {
    suppress_workspace_recording(state)
  }
  let invocation = saved_command(state)
  let invocation_sources = invocation.mapi((index, _) => "command[\{index}]")
  let (_, invocation_secrets, invocation_incomplete) = up_arguments_evidence(
    invocation, invocation_sources,
  )
  let logging = if devsy_progress_stage(stage) {
    ["--log-level", "debug", "--log-output", "json"]
  } else {
    []
  }
  let secrets = protected_values.unwrap_or([]) +
    extra_secrets.unwrap_or([]) +
    invocation_secrets
  let program = workspace_program(state, invocation[0])
  let cwd = workspace_directory(state).unwrap_or(
    @env.current_dir().unwrap_or("/"),
  )
  let lookup_path = match
    field(field(state, "devsyEnv").unwrap_or(Json::null()), "PATH") {
    Some(Json::String(value)) => value
    _ => "/usr/bin:/bin"
  }
  let path_protection = Progress::new(
    stage,
    environment~,
    protected_secrets=secrets,
    protection_incomplete=protected_values is None ||
      extra_protection_incomplete ||
      invocation_incomplete,
  )
  let lookup_path = redact_known_values(lookup_path, path_protection.secrets)
    .split(":")
    .map(entry => Json::string(entry.to_owned()))
    .to_array()
  let result = command_result(
    program,
    invocation[1:].to_owned() + devsy_args(state) + logging + args,
    stage,
    environment~,
    recording_override=state_recording(state),
    protected_secrets=secrets,
    protection_incomplete=protected_values is None ||
      extra_protection_incomplete ||
      invocation_incomplete,
    invocation_evidence={
      "command": Json::array(invocation.map(Json::string)),
      "resolvedProgram": program,
      "lookupPath": Json::array(lookup_path),
      "workingDirectory": cwd,
      "sshAuthSock": environment
      .get("SSH_AUTH_SOCK")
      .map(Json::string)
      .unwrap_or(Json::null()),
    },
    cwd?=workspace_directory(state).map(path => path[:]),
    target?=field(state, "workspaceId").map(value => {
      if value is Json::String(name) {
        name
      } else {
        ""
      }
    }),
  )
  result
}

