///|
fn diagnostic_health_snapshot() -> Json {
  if diagnostic_recording_health.incident ||
    diagnostic_recording_health.dropped > 0 {
    {
      "status": "degraded",
      "reason": diagnostic_recording_health.reason,
      "phase": diagnostic_recording_health.phase,
    }
  } else {
    { "status": "healthy" }
  }
}

///|
async fn publish_diagnostic_health() -> Unit {
  guard @env.args() is [_, "--supervisor", ..] else { return }
  @async.with_timeout(10, async fn() {
    let directory = adapter_state_home()
    let path = directory + "/diagnostic-health.json"
    if !diagnostic_recording_health.incident &&
      diagnostic_recording_health.dropped == 0 {
      @fs.remove(path) catch {
        _ => ()
      }
      return
    }
    let temporary = directory +
      "/diagnostic-health." +
      proxy_pid().to_string() +
      ".tmp"
    defer (@fs.remove(temporary) catch { _ => () })
    let snapshot = diagnostic_health_snapshot()
    set_field(snapshot, "runId", Json::string(recording_run_id))
    set_field(
      snapshot,
      "pendingEvents",
      Json::number(diagnostic_pending.length().to_double()),
    )
    set_field(
      snapshot,
      "droppedEvents",
      Json::number(diagnostic_recording_health.dropped.to_double()),
    )
    let mut first = if diagnostic_recording_health.dropped > 0 {
      Some(diagnostic_recording_health.first_dropped)
    } else {
      None
    }
    let mut last = if diagnostic_recording_health.dropped > 0 {
      Some(diagnostic_recording_health.last_dropped)
    } else {
      None
    }
    for pending in diagnostic_pending {
      if first is None || pending.time < first.unwrap() {
        first = Some(pending.time)
      }
      if last is None || pending.time > last.unwrap() {
        last = Some(pending.time)
      }
    }
    if first is Some(time) {
      set_field(snapshot, "missingFromTime", Json::string(time.to_string()))
    }
    if last is Some(time) {
      set_field(snapshot, "missingThroughTime", Json::string(time.to_string()))
    }
    if !diagnostic_previous_losses.is_empty() {
      set_field(snapshot, "priorLoss", Json::array(diagnostic_previous_losses))
    }
    @fs.write_file(temporary, snapshot.stringify(), permission=0o600)
    @fs.rename(temporary, path, replace=true)
  }) catch {
    _ => ()
  }
}

///|
async fn diagnostic_recording_warning(
  reason : String,
  phase~ : String = "",
  os_errno? : Int32,
) -> Unit {
  if reason == "workspace_recording_unknown" {
    diagnostic_recording_health.run_partial = true
  }
  let publish = !diagnostic_recording_health.incident ||
    diagnostic_recording_health.reason != reason ||
    diagnostic_recording_health.phase != phase
  diagnostic_recording_health.incident = true
  diagnostic_recording_health.incident_serial += 1
  if diagnostic_recording_health.dropped == 0 {
    diagnostic_recording_health.reason = reason
    diagnostic_recording_health.phase = phase
    diagnostic_recording_health.os_errno = os_errno
  }
  if publish {
    publish_diagnostic_health()
  }
  if !diagnostic_recording_health.warned {
    diagnostic_recording_health.warned = true
    @async.with_timeout(10, async fn() {
      @stdio.stderr.write(
        "orca-env-devsy: warning: diagnostic recording is unavailable (" +
        reason +
        (if phase == "" { "" } else { ", phase=" + phase }) +
        os_errno.map(code => ", errno=" + code.to_string()).unwrap_or("") +
        ")\n",
      )
    }) catch {
      _ => ()
    }
  }
}

///|
async fn diagnostic_recording_failed(
  reason : String,
  phase~ : String = "",
  os_errno? : Int32,
  event_time? : UInt64,
) -> Unit {
  let time = event_time.unwrap_or(@env.now())
  let health_changed = diagnostic_recording_health.reason != reason ||
    diagnostic_recording_health.phase != phase
  if diagnostic_recording_health.dropped == 0 {
    diagnostic_recording_health.first_dropped = time
    diagnostic_recording_health.last_dropped = time
  } else {
    if time < diagnostic_recording_health.first_dropped {
      diagnostic_recording_health.first_dropped = time
    }
    if time > diagnostic_recording_health.last_dropped {
      diagnostic_recording_health.last_dropped = time
    }
  }
  diagnostic_recording_health.dropped += 1
  diagnostic_recording_health.run_partial = true
  diagnostic_recording_health.reason = reason

