fn shell_wait_with_signals(command : String) -> String {
  "trap 'kill -s TERM \"$!\" 2>/dev/null || :; wait \"$!\" 2>/dev/null || :; exit 143' TERM; " +
  "trap 'kill -s INT \"$!\" 2>/dev/null || :; wait \"$!\" 2>/dev/null || :; exit 130' INT; " +
  "trap 'kill -s HUP \"$!\" 2>/dev/null || :; wait \"$!\" 2>/dev/null || :; exit 129' HUP; " +
  command +
  " & wait \"$!\""
}

