priv struct DiagnosticRecordingHealth {
  mut dropped : Int32
  mut first_dropped : UInt64
  mut last_dropped : UInt64
  mut reason : String
  mut phase : String
  mut os_errno : Int32?
  mut warned : Bool
  mut incident : Bool
