311	  value : Json,
312	  found : DiagnosticStructuredSecrets,
313	  secret~ : Bool = false,
314	  depth~ : Int32 = 0,
315	) -> Unit {
316	  if found.visited >= 65536 || depth >= 64 {
317	    found.incomplete = true
318	    return
319	  }
320	  found.visited += 1
321	  match value {
322	    Json::String(text) if secret && text != "" && text != "[redacted]" => {
323	      add_protected_secret(found.values, text)
324	      if found.values.length() > 512 {
325	        found.incomplete = true
326	      }
327	    }
328	    Json::Array(values) =>
329	      for item in values {
330	        if found.incomplete {
331	          break
332	        }
333	        diagnostic_structured_secrets(item, found, secret~, depth=depth + 1)
334	      }
335	    Json::Object(values) =>
336	      for name, item in values {
337	        if found.incomplete {
338	          break
339	        }
340	        let key = name.to_lower().replace_all(old="_", new="")
341	        diagnostic_structured_secrets(
342	          item,
343	          found,
344	          secret=secret ||
345	            credential_field(name, for_diagnostics=true) ||
346	            key == "pairingcode",
347	          depth=depth + 1,
348	        )
349	      }
350	    _ => ()
351	  }
352	}
