 899	  let now = @env.now()
 900	  if deadline <= now {
 901	    raise AdapterError(connection_timeout_message())
 902	  }
 903	  @async.with_timeout((deadline - now).to_int(), run, error=ConnectionDeadline) catch {
 904	    ConnectionDeadline => {
