 918	async fn wait_tunnel(
 919	  directory : String,
 920	  deadline : UInt64,
 921	  target : String,
 922	) -> Unit {
 923	  let started = @env.now()
 924	  progress_message(target + ": ssh-tunnel: connecting…")
 925	  errdefer progress_message(
 926	    target + ": ssh-tunnel: failed (" + progress_timing(started) + ")",
 927	  )
 928	  if @fs.exists(directory + "/worker-error.json") {
 929	    @fs.remove(directory + "/worker-error.json") catch {
 930	      _ => ()
 931	    }
 932	  }
 933	  @fs.write_file(directory + "/probe-request", "", permission=0o600)
 934	  connection_timeout(deadline, async fn() {
 935	    while true {
 936	      if connection_failure(directory, ["worker-error.json"]) is Some(detail) {
 937	        raise AdapterError("Connection recovery failed: " + detail)
 938	      }
 939	      let probe_pending = @fs.exists(directory + "/probe-request")
 940	      if @fs.exists(directory + "/status.json") {
 941	        let status = @json.parse(
 942	          @fs.read_file(directory + "/status.json").text(),
 943	        )
 944	        match field(status, "status") {
 945	          Some(Json::String("ownership-error")) => {
 946	            while worker_alive(directory) {
 947	              @async.sleep(25)
 948	            }
 949	            raise AdapterError("Tunnel workspace ownership changed")
 950	          }
 951	          Some(Json::String("workspace-stopped" | "workspace-busy" | "paused")) =>
 952	            ()
 953	          Some(Json::String("unsupported")) => {
 954	            while worker_alive(directory) {
 955	              @async.sleep(25)
 956	            }
 957	            raise AdapterError(
 958	              "Devsy /ready is unsupported; upgrade Devsy to a version supporting relay readiness",
 959	            )
 960	          }
 961	          Some(Json::String("connected")) if !probe_pending &&
 962	            worker_alive(directory) => {
 963	            let saved = @json.parse(
 964	              @fs.read_file(directory + "/state.json").text(),
 965	            )
 966	            try {
 967	              check_tunnel(saved, directory)
 968	              return
 969	            } catch {
 970	              _ => ()
 971	            }
 972	          }
 973	          _ => ()
 974	        }
 975	      }
 976	      @async.sleep(100)
 977	    }
 978	  }) catch {
 979	    AdapterError(message) => {
 980	      if !message.contains("SSH and relay readiness timed out") {
 981	        raise AdapterError(message)
 982	      }
 983	      let detail = connection_failure(directory, [
 984	        "worker-error.json", "ssh-error.json",
 985	      ]).unwrap_or("SSH failure details unavailable")
 986	      raise AdapterError(message + "; last connection failure: " + detail)
 987	    }
 988	    error => raise error
 989	  }
 990	  progress_message(
 991	    target + ": ssh-tunnel: connected (" + progress_timing(started) + ")",
 992	  )
 993	}
