 71	///|
 72	async fn launch_supervisor(
 73	  directory : String,
 74	  initial_workspace? : String,
 75	) -> Unit {
 76	  let sink = @process.redirect_to_file("/dev/null", shared=true)
 77	  defer sink.close()
 78	  let pid = @process.spawn_orphan(
 79	    saved_proxy_executable(),
 80	    ["--supervisor", directory] +
 81	    initial_workspace.map(value => [value]).unwrap_or([]),
 82	    stdin=@process.redirect_from_file("/dev/null"),
 83	    stdout=sink,
 84	    stderr=sink,
 85	  )
 86	  let process_identity = process_start(pid)
 87	  let started = @env.now()
 88	  save_diagnostic("supervisor-launch", "spawned", evidence={
 89	    "pid": pid,
 90	    "processStart": process_identity.to_string(),
 91	  })
 92	  errdefer {
 93	    let cancelled = @async.is_being_cancelled()
 94	    @async.protect_from_cancel(async fn() {
 95	      let observed = process_start(pid)
 96	      save_diagnostic(
 97	        "supervisor-launch",
 98	        if cancelled {
 99	          "cancelled"
100	        } else {
101	          "failed"
102	        },
103	        error_type=if observed < 0 {
104	          "process_inspection_failed"
105	        } else if observed == 0 {
106	          "process_exited"
107	        } else if process_identity > 0 && observed != process_identity {
108	          "process_replaced"
109	        } else {
110	          "startup_unconfirmed"
111	        },
112	        duration_ms=(@env.now() - started).to_double(),
113	        evidence={
114	          "pid": pid,
115	          "processStart": process_identity.to_string(),
116	          "observedProcessStart": observed.to_string(),
117	        },
118	      )
119	    })
120	  }
121	  while !supervisor_alive(directory) {
122	    @async.sleep(10)
123	  }
124	  save_diagnostic(
125	    "supervisor-launch",
126	    "ready",
127	    duration_ms=(@env.now() - started).to_double(),
128	    evidence={ "pid": pid },
129	  )
130	}
