570	async fn bulk_inner(
571	  mode : String,
572	  args : Array[String],
573	  recording_allowed : Ref[Bool],
574	) -> Int32 {
575	  let options = bulk_options(mode, args)
576	  save_diagnostic("bulk", "started", evidence={
577	    "action": mode,
578	    "provider": options.provider,
579	    "jobs": options.jobs,
580	    "force": options.force,
581	  })
582	  let base = adapter_state_home() + "/tunnels"
583	  let states : Array[Json] = []
584	  let discovery_errors : Array[Json] = []
585	  let discovery_secrets : Array[String] = []
586	  let mut discovery_recording = true
587	  if @fs.exists(base) {
588	    for name in @fs.readdir(base, sort=true) {
589	      let directory = base + "/" + name
590	      let mut discovery_phase = "kind"
591	      try {
592	        if @fs.kind(directory, follow_symlink=false) != @fs.FileKind::Directory ||
593	          !@fs.exists(directory + "/enabled") {
594	          continue
595	        }
596	        discovery_phase = "read"
597	        let raw = @fs.read_file(directory + "/state.json").text()
598	        discovery_phase = "parse"
599	        let state = @json.parse(raw)
600	        discovery_phase = "validate"
601	        validate_state(state)
602	        guard field(state, "devsyEnv") is Some(Json::Object(_)) else {
603	          raise AdapterError("Missing saved Devsy environment")
604	        }
605	        ignore(required(state, "workspaceUid"))
606	        ignore(required(state, "context"))
607	        set_field(state, "tunnelDirectory", Json::string(directory))
608	        set_field(state, "provider", Json::string(options.provider))
609	        snapshot_workspace_recording(state, directory)
610	        states.push(state)
611	      } catch {
612	        error => {
613	          discovery_errors.push({
614	            "savedState": directory,
615	            "reason": diagnostic_error(error),
616	          })
617	          let (allowed, secrets) = record_discovery_error(
618	            "bulk-discovery", directory, discovery_phase, error,
619	          )
620	          discovery_recording = discovery_recording && allowed
621	          for secret in secrets {
622	            discovery_secrets.push(secret)
623	          }
624	        }
625	      }
626	    }
627	  }
628	  recording_allowed.val = recording_allowed.val &&
629	    discovery_recording &&
630	    states.iter().all(workspace_recording)
631	  if !recording_allowed.val {
632	    diagnostic_recording_health.run_partial = true
633	  }
634	  let keys : Map[String, Int32] = Map([])
635	  for state in states {
636	    let key = required(state, "context") + ":" + required(state, "workspaceUid")
637	    keys.set(key, keys.get(key).unwrap_or(0) + 1)
638	  }
639	  let results : Array[Json] = []
640	  let permits = @async.Semaphore(options.jobs)
641	  @async.with_task_group(async fn(group) {
642	    for state in states {
643	      let key = required(state, "context") +
644	        ":" +
645	        required(state, "workspaceUid")
646	      if keys.get(key) != Some(1) {
647	        discovery_errors.push({
648	          "savedState": required(state, "tunnelDirectory"),
649	          "reason": "duplicate_saved_identity",
650	        })
651	        record_selection_failure(
652	          "bulk-discovery", state, "identity", "duplicate_saved_identity", "Duplicate saved workspace identity",
653	        )
654	        continue
655	      }
656	      permits.acquire()
657	      group.spawn_bg(async fn() {
658	        defer permits.release()
659	        if bulk_one(mode, state, options) is Some(result) {
660	          results.push(result)
661	        }
662	      })
663	    }
664	  })
665	  results.sort_by((a, b) => {
666	    let a_id = match field(a, "id") {
667	      Some(Json::String(id)) => id
668	      _ => ""
669	    }
670	    let b_id = match field(b, "id") {
671	      Some(Json::String(id)) => id
672	      _ => ""
673	    }
674	    a_id.compare(b_id)
675	  })
676	  let failures = results
677	    .filter(r => field(r, "outcome") == Some(Json::string("failed")))
678	    .length()
679	  let output : Json = {
680	    "schemaVersion": 1,
681	    "action": mode,
682	    "provider": options.provider,
683	    "workspaces": results,
684	    "failed": failures,
685	    "discoveryErrors": discovery_errors,
686	  }
687	  @stdio.stdout.write(output.stringify(indent=2) + "\n")
688	  recording_allowed.val = recording_allowed.val &&
689	    states.iter().all(workspace_recording)
690	  let secrets : Array[String] = [] + discovery_secrets
691	  for state in states {
692	    match saved_workspace_secrets(state) {
693	      Some(values) =>
694	        for secret in values {
695	          secrets.push(secret)
696	        }
697	      None => {
698	        suppress_workspace_recording(state)
699	        recording_allowed.val = false
700	      }
701	    }
702	  }
703	  if !recording_allowed.val {
704	    diagnostic_recording_health.run_partial = true
705	    record_batch_omission("bulk", states, discovery_recording)
706	  }
707	  save_diagnostic(
708	    "bulk",
709	    if failures > 0 {
710	      "failed"
711	    } else if !discovery_errors.is_empty() {
712	      "partial"
713	    } else {
714	      "success"
715	    },
716	    error_type?=if !discovery_errors.is_empty() {
717	      Some("saved_state_invalid")
718	    } else {
719	      None
720	    },
721	    evidence=output,
722	    evidence_incomplete=results
723	      .iter()
724	      .any(result => {
725	        field(result, "evidenceTruncated") == Some(Json::boolean(true))
726	      }),
727	    evidence_stable_activity=true,
728	    protected_secrets=secrets,
729	    recording=recording_allowed.val,
730	  )
731	
732	  failures
733	}

