   100	///|
   101	async fn settings_process(
   102	  program : String,
   103	  args : Array[String],
   104	  environment~ : Map[String, String],
   105	  input? : String,
   106	) -> String {
   107	  let (stdin, writer) = @process.write_to_process()
   108	  defer writer.close()
   109	  @async.with_task_group(async fn(group) {
   110	    let output = group.spawn(async fn() {
   111	      @process.collect_output(
   112	        program[:],
   113	        args[:],
   114	        extra_env=environment,
   115	        inherit_env=false,
   116	        stdin~,
   117	      )
   118	    })
   119	    if input is Some(value) {
   120	      writer.write(value)
   121	    }
   122	    writer.close()
   123	    let (status, stdout, stderr) = output.wait()
   124	    guard status == 0 else {
   125	      let (phase, code) = try {
   126	        let error = @json.parse(stderr.text())
   127	        let phase = required(error, "phase")
   128	        let code = required(error, "code")
   129	        if ["load", "read", "normalize", "input", "profile", "write", "verify"].contains(
   130	            phase,
   131	          ) &&
   132	          ["EACCES", "ENOENT", "EBUSY", "ENOSPC", "INCOMPATIBLE", "INVALID"].contains(
   133	            code,
   134	          ) {
   135	          (phase, code)
   136	        } else {
   137	          ("process", "process_exit")
   138	        }
   139	      } catch {
   140	        _ => ("process", "process_exit")
   141	      }
   142	      raise SettingsProcessError(phase, code, status)
   143	    }
   144	    guard stdout.binary().length() <= 4194304 else {
   145	      raise AdapterError("Orca settings result exceeds size limit")
   146	    }
   147	    stdout.text()
   148	  })
   149	}
