  1751	fn diagnostic_value(value : String?, kind : DiagnosticValueKind) -> Json {
  1752	  match value {
  1753	    None => { "state": "unset" }
  1754	    Some("") => { "state": "empty" }
  1755	    Some(text) => {
  1756	      let valid = match kind {
  1757	        Commit => valid_commit(text)
  1758	        Workspace => valid_workspace_id(text)
  1759	        Identity => text.length() <= 128 && valid_context(text)
  1760	        RefName => diagnostic_ref(text)
  1761	      }
  1762	      let credential_form = text
  1763	        .split("/")
  1764	        .iter()
  1765	        .any(part => {
  1766	          [
  1767	            "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "glpat-", "sk-",
  1768	            "eyJ",
  1769	          ]
  1770	          .iter()
  1771	          .any(prefix => part.has_prefix(prefix))
  1772	        })
  1773	      if credential_form {
  1774	        { "state": "redacted" }
  1775	      } else if valid {
  1776	        { "state": "valid", "value": text }
  1777	      } else {
  1778	        { "state": "invalid", "value": text }
  1779	      }
  1780	    }
  1781	  }
  1782	}
