  1790	  !text.contains("..") &&
  1791	  !text.contains("@{") &&
  1792	  text != "@" &&
  1793	  text
  1794	  .split("/")
  1795	  .iter()
  1796	  .all(part => {
  1797	    part != "" &&
  1798	    !part.has_prefix(".") &&
  1799	    !part.has_suffix(".") &&
  1800	    !part.has_suffix(".lock")
  1801	  }) &&
  1802	  text
  1803	  .iter()
  1804	  .all(c => {
  1805	    c > ' ' &&
  1806	    c != '\u007f' &&
  1807	    !['~', '^', ':', '?', '*', '[', '\\'].contains(c)
