  1912	///|
  1913	// Inspect only the strategy flags in the actual invocation. Other arguments
  1914	// never enter the diagnostic record. Devsy uses the last valid repeated flag.
  1915	fn diagnostic_clone_strategy(args : Array[String]) -> (String, String) {
  1916	  let mut strategy = "full"
  1917	  let mut count = 0
  1918	  let mut invalid = false
  1919	  let mut index = 0
  1920	  while index < args.length() {
  1921	    let argument = args[index]
  1922	    let value = if argument == "--git-clone-strategy" {
  1923	      count += 1
  1924	      index += 1
  1925	      if index < args.length() {
  1926	        Some(args[index])
  1927	      } else {
  1928	        None
  1929	      }
  1930	    } else if argument.has_prefix("--git-clone-strategy=") {
  1931	      count += 1
  1932	      Some(argument[21:].to_owned())
  1933	    } else {
  1934	      None
  1935	    }
  1936	    if count > 0 &&
  1937	      (
  1938	        argument == "--git-clone-strategy" ||
  1939	        argument.has_prefix("--git-clone-strategy=")
  1940	      ) {
  1941	      match value {
  1942	        Some("") => strategy = "full"
  1943	        Some("shallow" | "blobless" | "treeless" | "bare" as known) =>
  1944	          strategy = known
  1945	        _ => invalid = true

